entries[60503] = { ["name"] = "Starke Murlocpheromone", ["text"] = "Questgegenstand\nBenutzen: Bespritzt den Abgesandten der Moosfelle mit Murlocpheromonen, wodurch alle nahen Murlocs in heftige Raserei verfallen.\n\"NICHT AUF SICH ODER ANDERE RICHTEN. BEI HAUTKONTAKT: WEGLAUFEN!\"" }
entries[60504] = { ["name"] = "Painitbrocken", ["text"] = "Questgegenstand\n\"Sogar seine Facetten haben Facetten. Für die richtige Person ist er sicher sehr wertvoll.\"" }
